$ErrorActionPreference='Stop';$target=(Invoke-RestMethod 'http://127.0.0.1:9333/json/list').Where({$_.type -eq 'page'},'First')[0];$socket=[System.Net.WebSockets.ClientWebSocket]::new();$socket.ConnectAsync([Uri]$target.webSocketDebuggerUrl,[Threading.CancellationToken]::None).GetAwaiter().GetResult();$script:id=0
function Send-Cdp($method,$params){$script:id++;$requestId=$script:id;$json=@{id=$requestId;method=$method;params=$params}|ConvertTo-Json -Depth 8 -Compress;$bytes=[Text.Encoding]::UTF8.GetBytes($json);$socket.SendAsync([ArraySegment[byte]]$bytes,[System.Net.WebSockets.WebSocketMessageType]::Text,$true,[Threading.CancellationToken]::None).GetAwaiter().GetResult();while($true){$stream=[IO.MemoryStream]::new();do{$buffer=New-Object byte[] 1048576;$result=$socket.ReceiveAsync([ArraySegment[byte]]$buffer,[Threading.CancellationToken]::None).GetAwaiter().GetResult();$stream.Write($buffer,0,$result.Count)}while(-not $result.EndOfMessage);$response=[Text.Encoding]::UTF8.GetString($stream.ToArray())|ConvertFrom-Json;if($response.id -eq $requestId){return $response}}}
foreach($viewport in @(@{width=320;height=800},@{width=390;height=844},@{width=430;height=932})){Send-Cdp 'Emulation.setDeviceMetricsOverride' @{width=$viewport.width;height=$viewport.height;deviceScaleFactor=1;mobile=$true}|Out-Null;Send-Cdp 'Runtime.evaluate' @{expression='scrollTo(0,0)'}|Out-Null;Start-Sleep -Milliseconds 180;$expression="JSON.stringify({overflow:document.documentElement.scrollWidth-document.documentElement.clientWidth,scrollHeight:document.documentElement.scrollHeight,viewport:innerHeight})";$response=Send-Cdp 'Runtime.evaluate' @{expression=$expression;returnByValue=$true};Write-Output "$($viewport.width): $($response.result.result.value)";$shot=Send-Cdp 'Page.captureScreenshot' @{format='png';fromSurface=$true;captureBeyondViewport=$false};[IO.File]::WriteAllBytes("C:\Users\user\Downloads\day1-$($viewport.width)-18-basic-top.png",[Convert]::FromBase64String($shot.result.data))};$socket.Dispose()
